    }
}

int main(int argc, char *argv[]) {
    parse_args(argc, argv);

    if (x_mode) {
        printf("X window mode not fully implemented\n");
        return 0;
    }

    if (tty_set) {
        printf("Tty not set\n");
        return 0;
    }

    if (linux_mode) {
        setenv("TERM", "linux", 1);
    }

    if (force_term) {
        setenv("TERM", "xterm", 1);
    }

    if (message_mode) {
        if (lock_mode) {
