+static void init_ncurses(void) {
+    initscr();
+    cbreak();
+    noecho();
+    keypad(stdscr, TRUE);
+    curs_set(0);
+    if (linux_mode) {
+        set_term(&stdscr);
+    }
+}
+
+static void cleanup_ncurses(void) {
+    endwin();
+}
