+            
+            if (lambda_mode) {
+                mvaddch(i, j, 0x03BB);
+            } else {
+                mvaddch(i, j, chars[char_idx]);
+            }
+            
+            if (bold) {
+                attron(A_BOLD);
+            }
+            if (color_val != 0xFFFFFF) {
+                attron(COLOR_PAIR(1));
+            }
+            mvaddch(i, j, ' ');
+            if (bold) {
+                attroff(A_BOLD);
+            }
+            if (color_val != 0xFFFFFF) {
+                attroff(COLOR_PAIR(1));
+            }
+        }
+    }
+    
+    if (message_mode || lock_mode) {
+        int mid_row = rows / 2;
+        int mid_col = cols / 2;
+        int msg_len = strlen(message) + 2;
+        int msg_start = mid_col - msg_len / 2;
+        
+        for (i = 0; i < msg_len; i++) {
+            mvaddstr(mid_row, msg_start + i, message);
+        }
+    }
+    
+    if (screensaver) {
+        int ch;
+        while (1) {
+            ch = getch();
+            if (ch == 'q' || ch == 'Q') {
+                break;
+            }
+        }
+    }
+    
+    cleanup_ncurses();
+    return 0;
+}
